package GUI;
import javafx.geometry.Insets; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.scene.paint.Color; import java.util.function.Consumer;
public final class UIFactory {private UIFactory(){} public static Button button(String text,String style){Button b=new Button(text);b.getStyleClass().add(style);return b;} public static Label title(String text){Label l=new Label(text);l.getStyleClass().add("page-title");return l;} public static Label muted(String text){Label l=new Label(text);l.getStyleClass().add("muted");return l;} public static Label logoBadge(){Label badge=new Label("EI");badge.getStyleClass().add("ei-badge");return badge;} public static VBox page(String title,String subtitle){VBox root=new VBox(18);root.setPadding(new Insets(28,32,32,32));root.getChildren().addAll(title(title),muted(subtitle));return root;} public static void error(String message){alert(Alert.AlertType.ERROR,"Something needs attention",message);} public static void info(String title,String message){alert(Alert.AlertType.INFORMATION,title,message);} private static void alert(Alert.AlertType type,String title,String msg){Alert a=new Alert(type,msg,ButtonType.OK);a.setTitle(title);a.setHeaderText(null);a.showAndWait();} public static TextField field(String prompt){TextField f=new TextField();f.setPromptText(prompt);f.setMaxWidth(Double.MAX_VALUE);return f;} public static void grow(javafx.scene.Node n){HBox.setHgrow(n,Priority.ALWAYS);} }
